import{z as A,x as B,o as E,c as d,q as s,j as l,D as e,d as t,s as o,S as n,b as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SIEM","description":"","frontmatter":{"title":"SIEM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/siem-logging.md","filePath":"cs/siem-logging.md","lastUpdated":1791413859000}'),p={name:"cs/siem-logging.md"};function m(h,a,c,D,C,g){const r=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=s('<h1 id="siem" tabindex="-1">SIEM <a class="header-anchor" href="#siem" aria-label="Permalink to &quot;SIEM&quot;">​</a></h1><div class="epigraph"><p>安全信息和事件管理把日志汇聚、规范化、关联。没有可靠时间与身份字段，关联是噪音。日志完整性本身要防篡改，否则根kit 课的撒谎会延伸到记录。</p><footer>—— 据 NIST SP 800-92；对照可观测性课的三支柱只作点名</footer></div><p>上一课<a href="/cs/default-config-hardening">默认加固</a>要能证明配置改过，证明材料就是日志。缺口是<strong>把证据送走并关联</strong>。本课讲日志合同：时钟、身份、外送、保留。不写如何擦日志的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机本地日志在敌手拿下主机后可随手改写——rootkit 课的「撒谎」同样适用于日志文件。第一原则因此是外送：生成即发往聚合器、落只增存储，本地副本被清远端证据仍在。外送之后才谈得上关联，而关联的原料是字段：谁、何时、对何客体、成功失败——缺一列，规则就退化成「某 IP 失败次数多」这类既误报又漏报的东西。关联规则的误报经济学与 IDS 同类：阈值低则告警被忽略，高则真爆破漏过。</p><h3 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to &quot;隐私&quot;">​</a></h3><p>日志天然含个人数据：谁在何时登录、访问了什么，GDPR 课会回来算这笔账。设计时最小化字段，保留期写进合同。</p><p><span class="marginnote">数字实例：保留期要按事件类型写进合同——如「认证日志留 90 天、管理面操作留 1 年」。现实里入侵往往在发生后数月才被发现，响应时需要回放到三个月前的初始入口；日志总是比事件响应更早被需要，而不是相反。</span></p><p><span class="marginnote">SP 800-92。禁止日志伪造/擦除教程。事件响应下一课用这些证据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>最小事件集四类：认证成功与失败（爆破在此现形）、授权失败（越权尝试）、管理面操作（改配置、建账号）、出站连接（外送通道）。每类带齐四列字段，并单独验证时钟——NTP 不同步的机器拼不出因果序列。下一课事件响应生命周期。</p><p><span class="marginnote">直觉类比：关联规则像串珠成链——单条日志是一颗珠子（「张三登录成功」本身无善恶），按时间与身份串起来才成项链：「张三凌晨从陌生 IP 登录、五分钟后建了新管理员、随即导出数据库」，三颗珠子连起来才构成告警。</span></p>',13)),(E(),l(n,null,{default:e(()=>[o(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%B8%BB%E6%9C%BA%E4%B8%8E%E7%BD%91%E7%BB%9C%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20SHIP%5B%22%E5%A4%96%E9%80%81%22%5D%0A%20%20SHIP%20--%3E%20NORM%5B%22%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20CORR%5B%22%E5%85%B3%E8%81%94%E5%91%8A%E8%AD%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"SIEM 在栈里的位置是「观测」：它不挡任何攻击，产出的是「发生了什么」的有序序列，供下一课响应流程消费。时间的地位要单独钉：关联在时间轴上进行，两台时钟差几分钟的机器之间连因果方向都可能颠倒——所以时钟与身份是日志合同的前提条款，不是可选优化。观测是响应的输入，IR 下一课是流程。",-1)),(E(),l(n,null,{default:e(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20E1%5B%22%E5%90%8C%E4%B8%80%E6%9D%A5%E6%BA%90%E8%AE%A4%E8%AF%81%E5%A4%B1%E8%B4%A5%20x%20N%22%5D%20--%3E%20AGG%5B%22%E8%81%9A%E5%90%88%E5%99%A8%E6%8C%89%E5%9B%9B%E5%88%97%E5%AD%97%E6%AE%B5%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20E2%5B%22%E5%90%8C%E6%9D%A5%E6%BA%90%E9%9A%8F%E5%90%8E%E8%AE%A4%E8%AF%81%E6%88%90%E5%8A%9F%22%5D%20--%3E%20AGG%0A%20%20AGG%20--%3E%20R%7B%22%E8%A7%84%E5%88%99%3A%20%E5%A4%B1%E8%B4%A5%20%5Cgt%20%E9%98%88%E5%80%BC%20%E4%B8%94%20%E9%9A%8F%E5%90%8E%E6%88%90%E5%8A%9F%3F%22%7D%0A%20%20R%20--%3E%7C%E5%91%BD%E4%B8%AD%7C%20ALERT%5B%22%E5%91%8A%E8%AD%A6%3A%20%E7%96%91%E4%BC%BC%E7%88%86%E7%A0%B4%E5%BE%97%E6%89%8B%2C%20%E8%BD%AC%E4%BA%8B%E4%BB%B6%E5%93%8D%E5%BA%94%22%5D%0A%20%20R%20--%3E%7C%E6%9C%AA%E5%91%BD%E4%B8%AD%7C%20LOG%5B%22%E4%BB%85%E5%85%A5%E5%BA%93%E5%A4%87%E6%9F%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">常见误区：初学者容易以为日志「存下来」就等于安全。敌手拿下主机后的标准动作之一就是清本地日志——只有「生成即外送 + 只增存储」能让擦除失效。还要记住 SIEM 不挡攻击，它挡的是「事后赖账」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写清除或伪造日志的内容——那正是本课要防的失败模式。事件响应下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>加固要证据；SIEM 收证据。</li><li>外送与只增防篡改。</li><li>字段与时钟决定关联能否成立。</li><li>下一课事件响应。</li><li>出处：NIST SP 800-92。</li></ul>',5))])}const S=A(p,[["render",m]]);export{u as __pageData,S as default};
